# Google Docs re-markers every bullet as "*   " on a 4-space grid and flattens
# anything nested deeper than two levels.
EXPORTED_NESTED = """# 高中校舍願景論壇

## 內容詳述 Detailed Breakdown

### 論壇背景

*   起因是校舍老舊
    *   民國 60 年興建
    *   已超過使用年限
*   家長會提出訴求

---
"""


class Bullets(unittest.TestCase):
    def test_unedited_nested_list_reproduces_the_local_file(self):
        self.assertEqual(from_gdoc_markdown(EXPORTED_NESTED, LOCAL_NESTED), LOCAL_NESTED)

    def test_edited_bullet_keeps_the_new_text_at_local_marker_style(self):
        exported = EXPORTED_NESTED.replace("*   家長會提出訴求", "*   家長會提出改建訴求")
        out = from_gdoc_markdown(exported, LOCAL_NESTED)
        self.assertIn("\n- 家長會提出改建訴求\n", out)
        self.assertNotIn("家長會提出訴求\n", out)

    def test_bullet_added_in_the_doc_is_kept_at_its_exported_depth(self):
        exported = EXPORTED_NESTED.replace(
            "    *   民國 60 年興建", "    *   民國 60 年興建\n    *   工程分三期"
        )
        out = from_gdoc_markdown(exported, LOCAL_NESTED)
        self.assertIn("\n  - 工程分三期\n", out)

    def test_restored_depth_never_skips_a_level(self):
        # The grandparent was deleted in the doc; "已超過使用年限" must not be
        # re-indented to depth 2 with nothing above it.
        exported = EXPORTED_NESTED.replace("    *   民國 60 年興建\n", "")
        out = from_gdoc_markdown(exported, LOCAL_NESTED)
        self.assertIn("\n  - 已超過使用年限\n", out)


