# The doc's metadata block is the source of truth: a label renamed in Google
# Docs renames the field, a new label adds one, a removed label removes one.
EXPORTED_RENAMED = """# 高中校舍願景論壇

**導師：** 張三
**日期：** 2026-08-01
**紀錄：** 昀希爸爸

## 概述 Overview

這場論壇討論了校舍改建。

---
"""


class MetadataIsAuthoritative(unittest.TestCase):
    def setUp(self):
        self.out = from_gdoc_markdown(EXPORTED_RENAMED, LOCAL)
        self.meta = yaml.safe_load(self.out.split("---\n")[1])

    def test_unknown_label_becomes_a_frontmatter_field(self):
        self.assertEqual(self.meta["紀錄"], "昀希爸爸")

    def test_renamed_label_replaces_the_old_field(self):
        self.assertEqual(self.meta["導師"], "張三")
        self.assertNotIn("speaker", self.meta)

    def test_field_dropped_in_the_doc_is_dropped_locally(self):
        local = LOCAL.replace("speaker: 張三\n", "speaker: 張三\naudience: 家長\n")
        out = from_gdoc_markdown(EXPORTED_RENAMED, local)
        self.assertNotIn("audience", yaml.safe_load(out.split("---\n")[1]))

    def test_document_with_no_header_block_keeps_the_local_frontmatter(self):
        headless = "## 概述 Overview\n\n這場論壇討論了校舍改建。\n\n---\n"
        out = from_gdoc_markdown(headless, LOCAL)
        self.assertEqual(yaml.safe_load(out.split("---\n")[1]),
                         yaml.safe_load(LOCAL.split("---\n")[1]))

    def test_field_order_follows_the_document(self):
        self.assertEqual(list(self.meta), ["title", "導師", "date", "紀錄", "gdoc_id"])

    def test_gdoc_id_still_survives(self):
        self.assertEqual(self.meta["gdoc_id"], "1AbC_dEfGh")

    def test_unchanged_value_keeps_its_local_yaml_type(self):
        self.assertIn("date: 2026-08-01\n", self.out)


class MarkdownEscapes(unittest.TestCase):
    def test_escapes_google_docs_adds_are_removed(self):
        exported = EXPORTED.replace("這場論壇討論了校舍改建。", "會議結束\\~ 經費 3\\.5 萬")
        out = from_gdoc_markdown(exported, LOCAL)
        self.assertIn("會議結束~ 經費 3.5 萬", out)

    def test_escaped_bullet_text_still_matches_its_local_counterpart(self):
        exported = EXPORTED_NESTED.replace("家長會提出訴求", "家長會提出訴求\\!")
        out = from_gdoc_markdown(exported, LOCAL_NESTED)
        self.assertIn("\n- 家長會提出訴求!\n", out)
        self.assertNotIn("\\", out)


