class PartiallyFormattedHeader(unittest.TestCase):
    """A lost bold run must not take the rest of the frontmatter with it."""

    def test_a_label_that_lost_its_bold_is_still_read_as_metadata(self):
        out = from_gdoc_markdown(EXPORTED_UNBOLDED_LABEL, LOCAL_FULL_META)
        self.assertEqual(out, LOCAL_FULL_META)

    def test_the_fields_below_it_do_not_leak_into_the_body(self):
        out = from_gdoc_markdown(EXPORTED_UNBOLDED_LABEL, LOCAL_FULL_META)
        self.assertNotIn("**對象：**", out)
        self.assertNotIn("**目的：**", out)

    def test_an_unreadable_block_keeps_the_local_frontmatter(self):
        exported = (EXPORTED.replace("**講者：** 張三", "講者： 張三")
                            .replace("**日期：** 2026-08-01", "日期： 2026-08-01"))
        meta = yaml.safe_load(from_gdoc_markdown(exported, LOCAL).split("---\n")[1])
        self.assertEqual(meta, yaml.safe_load(LOCAL.split("---\n")[1]))

    def test_a_paragraph_that_is_not_metadata_stays_in_the_body(self):
        exported = EXPORTED.replace("**講者：** 張三\n**日期：** 2026-08-01",
                                    "開場：主持人致詞。")
        out = from_gdoc_markdown(exported, LOCAL)
        self.assertIn("開場：主持人致詞。", out)


class EmptyFrontmatterFields(unittest.TestCase):
    """gdoc.py cannot render a valueless field, so it must not be deleted."""

    def test_an_empty_field_survives_an_untouched_round_trip(self):
        local = LOCAL.replace("speaker: 張三\n", "speaker: 張三\nnotes: ''\n")
        exported = simulate_google_docs(gdoc.to_gdoc_markdown(local))
        self.assertEqual(from_gdoc_markdown(exported, local), local)

    def test_zero_and_false_are_values_and_are_rendered(self):
        local = LOCAL.replace("speaker: 張三\n", "count: 0\ndraft: false\nspeaker: 張三\n")
        uploaded = gdoc.to_gdoc_markdown(local)
        self.assertIn("**count：** 0", uploaded)
        self.assertIn("**draft：** False", uploaded)
        exported = simulate_google_docs(uploaded)
        self.assertEqual(from_gdoc_markdown(exported, local), local)


class FooterSurvivesInTheDoc(unittest.TestCase):
    """Google Docs sometimes keeps the italic generator line instead of eating it."""

    def _with_footer(self, copies=1):
        tail = "\n\n*Generated by video_summary using google/gemini-2.5-pro*"
        return EXPORTED.rstrip("\n") + tail * copies + "\n"

    def test_a_preserved_footer_is_not_duplicated(self):
        out = from_gdoc_markdown(self._with_footer(), LOCAL)
        self.assertEqual(out.count("*Generated by"), 1)
        self.assertEqual(out, LOCAL)

    def test_footers_stacked_by_an_earlier_sync_are_collapsed(self):
        out = from_gdoc_markdown(self._with_footer(copies=3), LOCAL)
        self.assertEqual(out.count("*Generated by"), 1)
        self.assertEqual(out, LOCAL)


class HardBreaks(unittest.TestCase):
    def test_trailing_backslash_line_breaks_do_not_reach_the_summary(self):
        exported = EXPORTED.replace("這場論壇討論了校舍改建。", "第一行\\\n第二行")
        out = from_gdoc_markdown(exported, LOCAL)
