class SectionAddedInTheDoc(unittest.TestCase):
    def setUp(self):
        exported = EXPORTED_LEGACY.replace(
            "\n---\n", "\n## 後續行動\n\n下次會議再議。\n\n---\n")
        self.out = from_gdoc_markdown(exported, LOCAL_LEGACY)

    def test_a_new_section_takes_the_shape_its_siblings_use(self):
        self.assertIn("**4. 後續行動**", self.out)
        self.assertNotIn("## 後續行動", self.out)

    def test_the_existing_sections_are_untouched(self):
        self.assertIn("**1. 概述**", self.out)
        self.assertIn("**3. 內容詳述**", self.out)

    def test_a_file_that_uses_real_headings_keeps_a_new_one(self):
        exported = EXPORTED_LOOSE.replace(
            "\n---\n", "\n## 後續行動\n\n下次會議再議。\n\n---\n")
        out = from_gdoc_markdown(exported, LOCAL_TIGHT)
        self.assertIn("## 後續行動", out)

    def test_its_bullets_are_siblings_rather_than_nested(self):
        # The section before this one ends at depth 1, and Google Docs exports
        # every item flat, so the depth must not carry across the new heading.
        exported = EXPORTED_LOOSE.replace(
            "\n---\n",
            "\n## 後續行動\n\n- 班代確認名單。\n- 財務組收費。\n\n---\n")
        out = from_gdoc_markdown(exported, LOCAL_TIGHT)
        self.assertIn("\n- 班代確認名單。\n- 財務組收費。\n", out)


class WriteSafety(unittest.TestCase):
    def setUp(self):
        self.dir = tempfile.mkdtemp()
        self.path = os.path.join(self.dir, "summary.md")
        with open(self.path, "w", encoding="utf-8") as f:
            f.write(LOCAL)
        self.out = io.StringIO()

    def tearDown(self):
        shutil.rmtree(self.dir)

    def _read(self):
        with open(self.path, encoding="utf-8") as f:
            return f.read()

    def test_a_failed_write_leaves_the_summary_intact(self):
        edited = EXPORTED.replace("校舍改建。", "校舍改建與經費。")
        with mock.patch.object(os, "replace", side_effect=OSError("disk full")):
            with self.assertRaises(OSError):
                gdoc_sync.sync(self.path, exporter=lambda _: edited,
                               confirm=lambda: True, out=self.out)
        self.assertEqual(self._read(), LOCAL)

    def test_a_failed_write_leaves_no_temp_file_behind(self):
        edited = EXPORTED.replace("校舍改建。", "校舍改建與經費。")
        with mock.patch.object(os, "replace", side_effect=OSError("disk full")):
            with self.assertRaises(OSError):
                gdoc_sync.sync(self.path, exporter=lambda _: edited,
                               confirm=lambda: True, out=self.out)
        self.assertEqual(os.listdir(self.dir), ["summary.md"])

    def test_the_file_mode_is_preserved(self):
        os.chmod(self.path, 0o640)
        edited = EXPORTED.replace("校舍改建。", "校舍改建與經費。")
        gdoc_sync.sync(self.path, exporter=lambda _: edited,
                       confirm=lambda: True, out=self.out)
        self.assertEqual(os.stat(self.path).st_mode & 0o777, 0o640)


class ErrorReporting(unittest.TestCase):
    def setUp(self):
        self.dir = tempfile.mkdtemp()
        self.path = os.path.join(self.dir, "summary.md")
        with open(self.path, "w", encoding="utf-8") as f:
            f.write(LOCAL)

    def tearDown(self):
        shutil.rmtree(self.dir)

    def _main(self, argv):
        err = io.StringIO()
        stderr, sys.stderr = sys.stderr, err
        try:
            return gdoc_sync.main(argv), err.getvalue()
        finally:
            sys.stderr = stderr

    def test_eof_on_the_prompt_declines_rather_than_raising(self):
        with mock.patch("builtins.input", side_effect=EOFError):
            self.assertFalse(gdoc_sync._ask())

    def test_a_missing_export_file_is_a_message_not_a_traceback(self):
        rc, err = self._main([self.path, "--from-file", os.path.join(self.dir, "nope.md")])
        self.assertEqual(rc, 1)
        self.assertIn("nope.md", err)

    def test_a_missing_summary_is_a_message_not_a_traceback(self):
        rc, err = self._main([os.path.join(self.dir, "gone.md"), "--doc-id", "abc"])
        self.assertEqual(rc, 1)
        self.assertIn("gone.md", err)

    def test_a_missing_gws_explains_itself(self):
        with mock.patch.object(gdoc_sync.subprocess, "run", side_effect=FileNotFoundError):
            with self.assertRaises(gdoc_sync.SyncError) as caught:
                gdoc_sync.export_doc("1AbC")
        self.assertIn("gws", str(caught.exception))

    def test_a_failed_export_explains_itself(self):
        error = subprocess.CalledProcessError(2, "gws")
        with mock.patch.object(gdoc_sync.subprocess, "run", side_effect=error):
            with self.assertRaises(gdoc_sync.SyncError) as caught:
                gdoc_sync.export_doc("1AbC")
        self.assertIn("1AbC", str(caught.exception))


class TestFileLayout(unittest.TestCase):
    def test_the_unittest_main_guard_is_the_last_thing_in_the_file(self):
        # Anywhere else and a direct `python3 tests/test_gdoc_sync.py` exits
        # before the classes below it are even defined.
        with open(__file__, encoding="utf-8") as f:
            source = f.read()
        self.assertTrue(
            source.rstrip().endswith('if __name__ == "__main__":\n    unittest.main()'))

if __name__ == "__main__":
    unittest.main()
